std::vector<Point2d> intersections;
for (size_t i = 0; i < segments.size(); ++i) {
    const Segment2d& seg1 = segments[i];
    for (size_t j = i + 1; j < segments.size(); ++j) {
        const Segment2d& seg2 = segments[j];

        Point2d p1From = seg1.p1();
        Point2d p1To   = seg1.p2();
        Point2d p2From = seg2.p1();
        Point2d p2To   = seg2.p2();

        double x1 = p1From.x(), y1 = p1From.y();
        double x2 = p1To.x(),   y2 = p1To.y();
        double x3 = p2From.x(), y3 = p2From.y();
        double x4 = p2To.x(),   y4 = p2To.y();

        double denom = (x1 - x2)*(y3 - y4) - (y1 - y2)*(x3 - x4);
        if (std::fabs(denom) < 1e-12) continue; // parallel or collinear

        double t = ((x1 - x3)*(y3 - y4) - (y1 - y3)*(x3 - x4)) / denom;
        double u = ((x1 - x3)*(y1 - y2) - (y1 - y3)*(x1 - x2)) / denom;

        if (t < 0.0 || t > 1.0 || u < 0.0 || u > 1.0) continue;

        double x = x1 + t * (x2 - x1);
        double y = y1 + t * (y2 - y1);

        intersections.emplace_back(x, y);
    }
}
return intersections;

